let seahorses, horse, fin
function preload() {
  horse = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/horse.png');
	fin = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/fin.png');
}

function setup() {
	seahorses = []
	createCanvas(windowWidth, windowHeight);
	for(let i = 0; i < 20; i++){
		seahorses.push(new Seahorse(horse,fin));
	}
	pg = createGraphics(width, height);

  // Draw to the graphics buffer.
  pg.background(0,51,102);
	pg.push()
	pg.translate(width/2,height/2)
	pg.stroke(255,5)

	pg.noFill()
	for(let j = -5; j <= 5; j++){
		pg.strokeWeight(int(random(10,50)))
		let off = random(TAU)
		pg.beginShape()
		for(let i = -width; i < width; i++){
			pg.vertex(i,sin(i*0.025+off)*25 + j*100)
		}
			pg.endShape()
	}
	pg.pop()
}

function draw() {
	image(pg,0,0)
	seahorses.forEach( seahorse =>{
		seahorse.update()
		seahorse.display()
	}
	)
}
